        event: event.to_string(),
        payload: payload.clone(),
        source: payload,
        guard: None,
        fans: true,
        completion: false,
    }]);
    let mut seen = std::collections::HashSet::new();
    let mut steps = 0;
    while let Some(item) = queue.pop_front() {
        let Some((state, entity)) = program.router().find(&item.target).map(|t| (t.state(), t.entity_json())) else { continue };
        let key = serde_json::json!([item.target, item.event, state, item.payload, entity]).to_string();
        if !item.completion && seen.contains(&key) {
            continue;
        }
        if let Some(guard) = item.guard {
            if !guard(&item.source) {
                continue;
            }
        }
        if steps >= 2000 {
            break;
        }
        steps += 1;
        seen.insert(key);
        let n = program.router().find(&item.target).map_or(0, |t| t.emitted_len());
        program.deliver(&item.target, &item.event, &item.payload);
        let router = program.router();
        let mut fanned = if item.fans { router.targets(&item.target, &item.event, &item.payload, false) } else { Vec::new() };
        let (new_state, emits) = router.find(&item.target).map_or((String::new(), Vec::new()), |t| (t.state(), t.emitted_from(n)));
        let mut own = Vec::new();
        for (ev, out, completion) in emits {
            router.log.push((item.target.clone(), ev.clone(), out.clone()));
            if router.handles.get(&item.target).and_then(|h| h.get(&new_state)).is_some_and(|evs| evs.contains(&ev)) {
                own.push(_Item { target: item.target.clone(), event: ev.clone(), payload: out.clone(), source: out.clone(), guard: None, fans: false, completion });
            }
            fanned.extend(router.targets(&item.target, &ev, &out, completion));
        }
        for x in own.into_iter().rev() {
            queue.push_front(x);
        }
        queue.extend(fanned);
    }
